"""id — prophets_c."""

T = {
"prophets_151": ("Apa yang dilarang didekati oleh Adam dan istrinya di surga?", ["Sebatang pohon", "Sebuah sungai", "Sebuah pintu", "Sebuah gunung"], "Allah membolehkan mereka makan sepuasnya, kecuali mendekati satu pohon saja."),
"prophets_152": ("Menurut Al-Qur'an, apa yang Adam terima dari Tuhannya setelah kekhilafannya?", ["Beberapa kalimat (tobat), dan Allah menerima tobatnya", "Kekayaan", "Sebuah kerajaan", "Sebuah kitab"], "«Lalu Adam menerima beberapa kalimat dari Tuhannya, maka Allah menerima tobatnya»."),
"prophets_153": ("Dengan siapa Al-Qur'an membandingkan Isa dalam hal penciptaannya?", ["Dengan Adam, yang diciptakan dari tanah", "Dengan Nuh", "Dengan Ibrahim", "Dengan Yahya"], "«Sesungguhnya perumpamaan Isa di sisi Allah seperti Adam: Dia menciptakannya dari tanah, kemudian berfirman kepadanya: “Jadilah!” maka jadilah dia»."),
"prophets_154": ("Tentang nabi manakah Al-Qur'an berkata bahwa ia seorang yang sangat benar dan Allah mengangkatnya ke tempat yang tinggi?", ["Idris", "Ilyas", "Zulkifli", "Ilyasa"], "«Dan ceritakanlah Idris di dalam Kitab: dia seorang yang sangat benar, seorang nabi; dan Kami telah mengangkatnya ke martabat yang tinggi»."),
"prophets_155": ("Apa yang Nuh ucapkan ketika kaumnya naik ke bahtera?", ["«Dengan nama Allah pada waktu berlayar dan berlabuhnya»", "«Jangan takut pada laut»", "«Bawalah bekal kalian»", "«Tunggulah malam»"], "«Naiklah kamu semua ke dalamnya: dengan nama Allah pada waktu berlayar dan berlabuhnya»."),
"prophets_156": ("Dalam surah Nuh, apa yang diminta Nabi Nuh kepada Tuhannya tentang orang-orang kafir?", ["Agar tidak menyisakan seorang pun dari mereka di bumi", "Agar menjadikan mereka kaya", "Agar memberi mereka setahun lagi", "Agar mengusir mereka"], "«Tuhanku, janganlah Engkau biarkan seorang pun di antara orang-orang kafir tinggal di atas bumi»."),
"prophets_157": ("Berapa banyak dari setiap jenis yang harus Nuh bawa ke bahtera?", ["Sepasang", "Tiga", "Sepuluh", "Satu saja"], "Allah memerintahkannya memuat sepasang dari setiap jenis, beserta keluarganya."),
"prophets_158": ("Hud mengingatkan kaum 'Ad bahwa Allah menjadikan mereka pengganti setelah kaum siapa?", ["Kaum Nuh", "Kaum Lut", "Kaum Musa", "Penduduk Saba"], "«Ingatlah ketika Dia menjadikan kamu pengganti setelah kaum Nuh dan menambahkan bagimu kelebihan dalam bentuk tubuh»."),
"prophets_159": ("Dengan apa kaum 'Ad dibinasakan menurut surah Al-Haqqah?", ["Dengan angin yang sangat dingin dan menderu", "Dengan banjir", "Dengan gempa", "Dengan serbuan belalang"], "«Adapun kaum 'Ad, mereka dibinasakan dengan angin yang sangat dingin lagi kencang»."),
"prophets_160": ("Apa yang Hud cela dari kaumnya yang membangun di setiap tempat tinggi?", ["Membangun karena kesia-siaan dan berharap hidup kekal", "Bercocok tanam", "Berdagang jauh", "Bepergian malam hari"], "«Apakah kamu mendirikan bangunan di setiap tanah tinggi untuk bermain-main? Dan kamu membuat benteng-benteng seolah kamu hidup kekal?»"),
"prophets_161": ("Apa yang dilakukan kaum Tsamud terhadap gunung-gunung menurut Al-Qur'an?", ["Mereka memahat rumah-rumah darinya", "Mereka menyembunyikan emas di dalamnya", "Mereka menggembala di atasnya", "Mereka menghindarinya"], "«Kamu dirikan istana-istana di tanah datarnya dan kamu pahat gunung-gunungnya menjadi rumah»."),
"prophets_162": ("Menurut surah Al-Qamar, unta itu dikirim kepada Tsamud sebagai apa?", ["Sebagai ujian bagi mereka", "Sebagai ganjaran", "Sebagai hadiah raja mereka", "Sebagai ternak untuk dijual"], "«Sesungguhnya Kami akan mengirim unta betina sebagai ujian bagi mereka: maka tunggulah mereka dan bersabarlah»."),
"prophets_163": ("Apa yang menimpa kaum Tsamud setelah mereka membunuh unta itu?", ["Gempa (ar-rajfah)", "Banjir", "Angin dingin", "Kelaparan"], "«Maka mereka ditimpa gempa, lalu jadilah mereka mayat-mayat yang bergelimpangan di tempat tinggal mereka»."),
"prophets_164": ("Nabi manakah yang diutus kepada kaum yang melakukan kekejian besar dan berkata «Tidakkah kamu bertakwa?»", ["Lut", "Saleh", "Hud", "Syuaib"], "«Ketika saudara mereka Lut berkata kepada mereka: “Tidakkah kamu bertakwa?”»"),
"prophets_165": ("Apa yang diperintahkan kepada Lut pada malam azab?", ["Pergi malam hari bersama keluarganya dan tidak menoleh ke belakang", "Mengumpulkan kaumnya", "Menunggu fajar", "Bersembunyi di gunung"], "«Maka pergilah dengan keluargamu pada sebagian malam, dan janganlah seorang pun di antara kamu menoleh ke belakang»."),
"prophets_166": ("Nabi manakah yang diutus kepada penduduk Madyan yang curang dalam takaran dan timbangan?", ["Syuaib", "Lut", "Hud", "Ilyas"], "Syuaib memerintahkan mereka menyempurnakan takaran dan timbangan, dan tidak berbuat kerusakan di bumi."),
"prophets_167": ("Apa yang Syuaib katakan kepada kaumnya tentang apa yang sungguh ia inginkan?", ["«Aku hanya bermaksud mendatangkan perbaikan sekuat kemampuanku»", "«Aku hanya ingin kekayaan»", "«Aku ingin berkuasa»", "«Aku ingin pergi»"], "«Aku hanya bermaksud mendatangkan perbaikan sekuat kemampuanku. Dan keberhasilanku hanya bergantung pada Allah»."),
"prophets_168": ("Setelah Allah menguji Ibrahim dengan perintah yang ia tunaikan, apa yang Dia katakan kepadanya?", ["«Aku akan menjadikanmu pemimpin (imam) bagi manusia»", "«Aku akan memberimu kerajaan»", "«Aku akan menjadikanmu kaya»", "«Aku akan menjadikanmu raja Babilonia»"], "«Aku akan menjadikanmu pemimpin bagi manusia». Ibrahim bertanya: «Dan dari keturunanku?»"),
"prophets_169": ("Bagaimana Ibrahim membungkam raja yang mengaku dapat menghidupkan dan mematikan?", ["«Allah menerbitkan matahari dari timur: maka terbitkanlah dari barat»", "«Turunkan hujan»", "«Pindahkan gunung itu»", "«Hitunglah bintang»"], "«Allah menerbitkan matahari dari timur; maka terbitkanlah ia dari barat». Maka terdiamlah orang kafir itu."),
"prophets_170": ("Apa yang diperintahkan kepada Ibrahim untuk diserukan kepada manusia tentang Rumah Suci?", ["Haji: mereka akan datang berjalan kaki dan dengan segala tunggangan", "Perdagangan", "Peperangan", "Diam"], "«Dan serukanlah kepada manusia untuk mengerjakan haji: niscaya mereka akan datang kepadamu dengan berjalan kaki dan mengendarai unta yang kurus»."),
"prophets_171": ("Apa yang Ibrahim hidangkan kepada tamu-tamunya yang mulia, yang tidak mereka sentuh?", ["Anak sapi gemuk yang dipanggang", "Roti dan air", "Kurma", "Susu"], "Ia pergi kepada keluarganya lalu membawa anak sapi gemuk; melihat tangan mereka tidak menjamahnya, ia merasa takut."),
"prophets_172": ("Tentang siapa Al-Qur'an berkata bahwa ia «teladan yang baik» (uswah hasanah) bagi orang beriman, bersama mereka yang menyertainya?", ["Ibrahim", "Nuh", "Musa", "Daud"], "«Sungguh telah ada suri teladan yang baik bagimu pada Ibrahim dan orang-orang yang bersama dia»."),
"prophets_173": ("Dalam surah Ibrahim, apa yang Ibrahim mohonkan untuk kota Makkah?", ["Agar aman, dan agar ia serta anak-anaknya dijauhkan dari menyembah berhala", "Agar menjadi pasar besar", "Agar memiliki istana", "Agar tetap kosong"], "«Tuhanku, jadikanlah negeri ini aman, dan jauhkanlah aku beserta anak cucuku dari menyembah berhala»."),
"prophets_174": ("Apa yang Ibrahim katakan ketika meninggalkan kaumnya?", ["«Aku pergi kepada Tuhanku: Dia akan memberiku petunjuk»", "«Aku pergi mencari kekayaan»", "«Aku akan kembali memerangi mereka»", "«Aku pergi ke Mesir»"], "«Sesungguhnya aku pergi kepada Tuhanku: Dia akan memberiku petunjuk»."),
"prophets_175": ("Tentang nabi manakah Al-Qur'an berkata bahwa ia «menepati janji» dan menyuruh keluarganya salat dan zakat?", ["Ismail", "Ishak", "Yakub", "Yusuf"], "«Sesungguhnya dia adalah orang yang menepati janji; dia seorang rasul dan nabi. Dia menyuruh keluarganya salat dan menunaikan zakat»."),
"prophets_176": ("Apa yang Yakub nasihatkan kepada Yusuf setelah mimpinya?", ["Agar tidak menceritakannya kepada saudara-saudaranya", "Agar menceritakannya kepada semua orang", "Agar menuliskannya", "Agar melupakannya"], "«Wahai anakku, janganlah engkau ceritakan mimpimu kepada saudara-saudaramu, nanti mereka membuat tipu daya terhadapmu»."),
"prophets_177": ("Bukti apa yang menetapkan kesucian Yusuf di hadapan tuan rumah?", ["Bajunya yang koyak di bagian belakang", "Saksi yang bersembunyi", "Sepucuk surat", "Sebuah sumpah"], "Jika baju itu koyak di belakang, maka perempuan itu berdusta dan Yusuf termasuk orang yang benar."),
"prophets_178": ("Apa yang dilakukan para perempuan kota ketika melihat Yusuf?", ["Mereka melukai tangan mereka karena kagum", "Mereka melarikan diri", "Mereka terdiam", "Mereka tertawa"], "«Ketika mereka melihatnya, mereka terpesona dan melukai tangan mereka seraya berkata: “Mahasempurna Allah! Ini bukanlah manusia; ini benar-benar malaikat yang mulia!”»"),
"prophets_179": ("Apa yang Yusuf ajarkan kepada dua teman penjaranya sebelum menakwilkan mimpi mereka?", ["Keesaan Allah, dan bahwa hukum hanya milik-Nya", "Ilmu kedokteran", "Perhitungan panen", "Syair"], "«Manakah yang lebih baik, tuhan-tuhan yang bermacam-macam atau Allah Yang Maha Esa lagi Mahaperkasa? … Keputusan itu hanyalah milik Allah»."),
"prophets_180": ("Apa yang raja Mesir katakan kepada Yusuf setelah berbicara dengannya?", ["«Hari ini engkau di sisi kami berkedudukan tinggi dan dipercaya»", "«Kembalilah ke penjara»", "«Keluarlah dari Mesir»", "«Kunikahkan engkau dengan putriku»"], "«Setelah dia bercakap-cakap dengannya, dia berkata: “Sesungguhnya engkau mulai hari ini menjadi seorang yang berkedudukan tinggi di lingkungan kami dan dipercaya”»."),
"prophets_181": ("Bagaimana Yusuf menahan saudaranya agar tetap bersamanya?", ["Piala raja ditemukan di karung saudaranya", "Ia membelinya", "Ia memenjarakannya tanpa sebab", "Ia menjadikannya menteri"], "«Demikianlah Kami atur untuk Yusuf»: piala itu keluar dari karung saudaranya."),
"prophets_182": ("Apa yang Yusuf katakan kepada saudara-saudaranya ketika mereka mengakui kesalahan?", ["«Pada hari ini tidak ada cercaan terhadap kamu»", "«Kamu akan dihukum»", "«Pergilah dan jangan kembali»", "«Aku telah melupakan kalian»"], "«Pada hari ini tidak ada cercaan terhadap kamu. Semoga Allah mengampuni kamu: Dia Maha Penyayang di antara para penyayang»."),
"prophets_183": ("Apa yang Yakub katakan kepada anak-anaknya tentang keputusasaan?", ["«Janganlah berputus asa dari rahmat Allah»", "«Jangan pergi lagi»", "«Jangan berbicara dengan siapa pun»", "«Jangan menulis apa pun»"], "«Dan jangan kamu berputus asa dari rahmat Allah: sesungguhnya yang berputus asa dari rahmat Allah hanyalah kaum yang kafir»."),
"prophets_184": ("Doa apa yang Yusuf panjatkan di akhir kisahnya?", ["Wafat dalam keadaan berserah diri (muslim) dan digabungkan dengan orang-orang saleh", "Menguasai seluruh Mesir", "Kembali ke Kanaan", "Berumur panjang"], "«Wafatkanlah aku dalam keadaan muslim dan gabungkanlah aku dengan orang-orang saleh»."),
"prophets_185": ("Bagaimana Ayyub menyeru Tuhannya dalam ujian?", ["«Aku ditimpa penyakit, dan Engkau Maha Penyayang»", "«Mengapa aku?»", "«Kembalikan kekayaanku»", "«Binasakan musuhku»"], "«Dan ingatlah hamba Kami Ayyub ketika dia menyeru Tuhannya: “Sesungguhnya setan telah menimpakan kepadaku penderitaan dan azab”»."),
"prophets_186": ("Apa yang Allah kembalikan kepada Ayyub setelah ujian, menurut surah Sad?", ["Keluarganya, dan sebanyak itu pula bersama mereka", "Sebuah kerajaan", "Sebuah kapal", "Sekawanan unta"], "«Dan Kami anugerahkan kepadanya keluarganya dan sebanyak itu pula bersama mereka, sebagai rahmat dari Kami dan pelajaran bagi orang yang berakal»."),
"prophets_187": ("Menurut surah As-Saffat, apa yang menyelamatkan Yunus dari tetap tinggal di perut ikan?", ["Bahwa ia termasuk orang yang bertasbih", "Kekuatannya", "Sebuah kapal yang lewat", "Angin yang baik"], "«Sekiranya dia tidak termasuk orang yang bertasbih, niscaya dia akan tetap tinggal di perutnya sampai hari kebangkitan»."),
"prophets_188": ("Kaum manakah yang menurut Al-Qur'an beriman sebelum azab menimpa dan iman itu bermanfaat bagi mereka?", ["Kaum Yunus", "Kaum Nuh", "Kaum Lut", "Kaum Hud"], "«Maka mengapa tidak ada satu negeri pun yang beriman lalu imannya bermanfaat baginya, selain kaum Yunus?»"),
"prophets_189": ("Bagaimana Al-Qur'an menyebut Yunus ketika Nabi ﷺ diperintahkan agar tidak seperti dia dalam ketergesaan?", ["«Orang yang berada dalam perut ikan» (sahibul-hut)", "«Pemilik tongkat»", "«Orang gunung»", "«Orang sumur»"], "«Dan janganlah engkau seperti orang yang berada dalam perut ikan ketika dia berdoa dalam keadaan sangat marah»."),
"prophets_190": ("Nabi manakah yang mencela kaumnya karena menyembah Ba'l dan meninggalkan sebaik-baik pencipta?", ["Ilyas", "Ilyasa", "Yunus", "Syuaib"], "«Dan sungguh Ilyas termasuk salah seorang rasul… “Pantaskah kamu menyembah Ba'l dan meninggalkan sebaik-baik pencipta?”»"),
"prophets_191": ("Bersama Ismail dan Idris, nabi manakah yang Al-Qur'an sebut di antara orang-orang sabar yang Allah masukkan ke dalam rahmat-Nya?", ["Zulkifli", "Ilyas", "Yunus", "Ilyasa"], "«Dan Ismail, Idris, dan Zulkifli: mereka semua termasuk orang-orang yang sabar. Dan Kami masukkan mereka ke dalam rahmat Kami»."),
"prophets_192": ("Apa yang Allah lakukan bagi Bani Israil di laut ketika dikejar Firaun?", ["Dia membelah laut dan menyelamatkan mereka", "Dia menurunkan malam", "Dia mengirim kapal", "Dia mengeringkan laut selamanya"], "«Dan ingatlah ketika Kami membelah laut untukmu: Kami selamatkan kamu dan Kami tenggelamkan pengikut Firaun»."),
"prophets_193": ("Mengapa Musa meminta Allah mengutus Harun bersamanya?", ["Karena dia lebih fasih lidahnya", "Karena dia lebih tua", "Karena dia mengenal Mesir", "Karena dia bisa menulis"], "«Dan saudaraku Harun, dia lebih fasih lidahnya daripada aku: maka utuslah dia bersamaku sebagai pembantu yang membenarkan aku»."),
"prophets_194": ("Bagaimana Musa dan Harun harus berbicara kepada Firaun?", ["Dengan kata-kata yang lemah lembut", "Dengan ancaman", "Tanpa memandangnya", "Hanya secara tertulis"], "«Berbicaralah kamu berdua kepadanya dengan kata-kata yang lemah lembut: mudah-mudahan dia sadar atau takut»."),
"prophets_195": ("Siapa dari keluarga Firaun yang membela Musa sambil menyembunyikan imannya?", ["Seorang laki-laki beriman dari keluarga Firaun", "Kepala pendeta", "Panglima tentara", "Wazir Haman"], "«Dan seorang laki-laki beriman dari keluarga Firaun yang menyembunyikan imannya berkata: “Apakah kamu akan membunuh seseorang karena dia berkata: Tuhanku ialah Allah?”»"),
"prophets_196": ("Apa yang Harun katakan kepada kaumnya selama Musa tidak ada?", ["Bahwa mereka hanya sedang diuji dengan anak sapi itu dan hendaknya mengikutinya", "Agar menyimpan anak sapi itu", "Agar berangkat ke Mesir", "Agar diam"], "«Wahai kaumku! Sesungguhnya kamu hanya diberi cobaan dengan itu. Tuhanmu adalah Yang Maha Pengasih: maka ikutilah aku»."),
"prophets_197": ("Apa yang istri Firaun katakan ketika menemukan bayi Musa?", ["«Dia akan menjadi penyejuk mata bagiku dan bagimu: jangan bunuh dia»", "«Kembalikan dia kepada ibunya»", "«Bawa dia ke sungai»", "«Juallah dia»"], "«Dan istri Firaun berkata: “Dia adalah penyejuk mata hati bagiku dan bagimu. Janganlah kamu membunuhnya: mudah-mudahan dia bermanfaat bagi kita”»."),
"prophets_198": ("Bagaimana Musa meminta izin mengikuti hamba yang berilmu (al-Khidr)?", ["«Bolehkah aku mengikutimu, dengan syarat engkau mengajariku?»", "«Perintahkan aku dan aku menaati»", "«Ajari aku dengan upah»", "«Ikutlah bersamaku»"], "«Bolehkah aku mengikutimu agar engkau mengajarkan kepadaku ilmu yang benar yang telah diajarkan kepadamu?»"),
"prophets_199": ("Dalam keadaan bagaimana Musa kembali kepada kaumnya setelah melihat anak sapi itu?", ["Marah dan sedih", "Gembira", "Diam", "Acuh tak acuh"], "«Dan ketika Musa kembali kepada kaumnya dengan marah dan sedih… dia melemparkan lauh-lauh itu»."),
"prophets_200": ("Pesan apa yang harus Musa bawa kepada Firaun menurut surah An-Nazi'at?", ["«Adakah keinginanmu untuk menyucikan diri, dan aku akan menunjukkanmu ke jalan Tuhanmu?»", "«Kembalikan kaumku»", "«Bangunkan aku sebuah istana»", "«Keluarlah dari Mesir»"], "«Pergilah kepada Firaun: sesungguhnya dia telah melampaui batas. Dan katakanlah: adakah keinginanmu untuk menyucikan diri, dan aku akan membimbingmu kepada Tuhanmu agar engkau takut kepada-Nya?»"),
"prophets_201": ("Siapa yang bertasbih bersama Daud, pada waktu petang dan pagi?", ["Gunung-gunung dan burung-burung", "Sungai-sungai", "Bintang-bintang", "Angin"], "«Sungguh Kami menundukkan gunung-gunung untuk bertasbih bersamanya pada waktu petang dan pagi, dan burung-burung yang terkumpul»."),
"prophets_202": ("Menurut Al-Qur'an, apa yang Allah berikan kepada Daud bersama kerajaan yang kokoh?", ["Hikmah dan kepandaian memutuskan perkara", "Pasukan yang besar", "Emas dan perak", "Istana dari gading"], "«Dan Kami kuatkan kerajaannya dan Kami berikan kepadanya hikmah dan kebijaksanaan dalam memutuskan perkara»."),
"prophets_203": ("Apa yang diperintahkan kepada Daud dalam membuat baju besi?", ["Mengukur anyamannya dengan tepat", "Mengukir namanya", "Menyepuhnya dengan emas", "Menjualnya"], "«Buatlah baju besi yang besar-besar dan ukurlah anyamannya»."),
"prophets_204": ("Apa yang Daud dan Sulaiman ucapkan ketika Allah memberi mereka ilmu?", ["«Segala puji bagi Allah yang melebihkan kami atas banyak hamba-hamba-Nya yang beriman»", "«Kamilah yang terbaik»", "«Tak ada yang menyamai kami»", "«Kami memang pantas»"], "«Segala puji bagi Allah yang melebihkan kami atas banyak hamba-hamba-Nya yang beriman»."),
"prophets_205": ("Apa yang Sulaiman lakukan ketika mendengar semut memperingatkan kaumnya?", ["Dia tersenyum dan memohon agar Allah menjadikannya bersyukur", "Dia marah", "Dia mengalihkan pasukannya diam-diam", "Dia memerintahkan diam"], "«Maka dia tersenyum lalu tertawa karena perkataan semut itu dan berkata: “Ya Tuhanku, anugerahkanlah aku ilham untuk mensyukuri nikmat-Mu”»."),
"prophets_206": ("Berita apa yang dibawa burung hudhud kepada Sulaiman?", ["Bahwa seorang perempuan memerintah Saba dan kaumnya sujud kepada matahari", "Bahwa pasukan mendekat", "Bahwa terjadi kekeringan", "Bahwa ada harta terpendam"], "«Aku datang kepadamu dari negeri Saba membawa berita yang meyakinkan: aku dapati seorang perempuan memerintah mereka… mereka sujud kepada matahari»."),
"prophets_207": ("Apa yang mengherankan ratu Saba ketika memasuki istana Sulaiman?", ["Lantai kaca yang dikiranya air", "Seekor singa jinak", "Taman gantung", "Singgasana emas"], "«Dikatakan kepadanya: “Masuklah ke dalam istana”. Ketika dia melihatnya, dikiranya kolam air lalu disingkapkannya kedua betisnya. Sulaiman berkata: “Ini adalah istana yang dilapisi kaca”»."),
"prophets_208": ("Terdiri dari apa pasukan Sulaiman menurut Al-Qur'an?", ["Dari jin, manusia, dan burung", "Hanya dari penunggang kuda", "Dari pelaut", "Hanya dari pemanah"], "«Dan dihimpunkan untuk Sulaiman bala tentaranya dari jin, manusia, dan burung, lalu mereka diatur dengan tertib»."),
"prophets_209": ("Bagaimana Zakaria menggambarkan keadaannya saat menyeru Tuhannya?", ["«Tulangku telah lemah dan kepalaku telah dipenuhi uban»", "«Aku kaya dan kenyang»", "«Aku jauh dari kaumku»", "«Aku sedang bepergian»"], "«Ya Tuhanku, sungguh tulangku telah lemah dan kepalaku telah dipenuhi uban, dan aku belum pernah kecewa dalam berdoa kepada-Mu»."),
"prophets_210": ("Tanda apa yang diberikan kepada Zakaria atas kelahiran Yahya?", ["Tidak dapat berbicara kepada manusia selama tiga hari kecuali dengan isyarat", "Sebuah bintang", "Hujan di luar musim", "Mimpi yang berulang"], "«Tandamu ialah engkau tidak dapat berbicara dengan manusia selama tiga hari kecuali dengan isyarat»."),
"prophets_211": ("Apa yang dikatakan kepada Yahya tentang Kitab?", ["«Ambillah Kitab itu dengan sungguh-sungguh»", "«Sembunyikan Kitab itu»", "«Salinlah Kitab itu»", "«Bacalah sekali»"], "«Wahai Yahya, ambillah Kitab itu dengan sungguh-sungguh!» Dan Kami berikan hikmah kepadanya selagi dia masih kanak-kanak."),
"prophets_212": ("Apa yang para malaikat perintahkan kepada Maryam setelah mengabarkan pilihannya?", ["Taat kepada Tuhannya, bersujud dan rukuk", "Melakukan perjalanan", "Diam selamanya", "Mengajar di Bait Suci"], "«Wahai Maryam, taatlah kepada Tuhanmu, bersujudlah dan rukuklah bersama orang-orang yang rukuk»."),
"prophets_213": ("Apa yang diperintahkan kepada Maryam untuk digoyangkan agar dapat makan saat melahirkan?", ["Pangkal pohon kurma, agar jatuh kurma segar", "Pohon zaitun", "Pohon tin", "Pohon anggur"], "«Dan goyanglah pangkal pohon kurma itu ke arahmu: niscaya akan berjatuhan kepadamu kurma yang masak»."),
"prophets_214": ("Apa yang Isa katakan di buaian tentang yang Allah perintahkan kepadanya?", ["Salat dan zakat selama dia hidup", "Perdagangan", "Diam", "Perjalanan"], "«Dan Dia memerintahkan kepadaku salat dan zakat selama aku hidup»."),
"prophets_215": ("Bagaimana surah Az-Zukhruf menggambarkan Isa putra Maryam?", ["Seorang hamba yang Allah beri nikmat dan Dia jadikan teladan bagi Bani Israil", "Seorang raja Israil", "Seorang malaikat yang turun", "Seorang juru tulis Bait Suci"], "«Dia tidak lain hanyalah seorang hamba yang Kami berikan nikmat kepadanya dan Kami jadikan dia sebagai contoh bagi Bani Israil»."),
"prophets_216": ("Apa yang akan Isa jawab pada hari kiamat ketika Allah bertanya kepadanya?", ["«Mahasuci Engkau! Tidak patut bagiku mengatakan apa yang bukan hakku»", "«Aku tidak ingat»", "«Merekalah yang menulis»", "«Tanyalah para pengikut»"], "«Mahasuci Engkau! Tidak patut bagiku mengatakan apa yang bukan hakku»."),
"prophets_217": ("Bagaimana Al-Qur'an menggambarkan Isa putra Maryam?", ["Utusan Allah, kalimat-Nya yang disampaikan kepada Maryam, dan roh dari-Nya", "Malaikat yang diutus", "Raja yang adil", "Juru tulis yang alim"], "«Al-Masih Isa putra Maryam itu hanyalah utusan Allah dan kalimat-Nya yang disampaikan-Nya kepada Maryam, dan roh dari-Nya»."),
"prophets_218": ("Dalam surah Ad-Duha, nikmat apa yang Allah ingatkan kepada Nabi-Nya ﷺ?", ["Dia melindunginya sebagai yatim, memberinya petunjuk, dan mencukupkannya", "Dia memberinya kerajaan", "Dia memberinya pasukan", "Dia memberinya istana"], "«Bukankah Dia mendapatimu sebagai yatim lalu Dia melindungimu? Dan Dia mendapatimu dalam keadaan bingung lalu Dia memberi petunjuk? Dan Dia mendapatimu kekurangan lalu Dia mencukupkan?»"),
"prophets_219": ("Janji apa yang diulang dua kali dalam surah Asy-Syarh?", ["«Sesungguhnya bersama kesulitan ada kemudahan»", "«Kemenangan sudah dekat»", "«Surga telah dijanjikan»", "«Musuh akan binasa»"], "«Maka sesungguhnya bersama kesulitan ada kemudahan. Sesungguhnya bersama kesulitan ada kemudahan»."),
"prophets_220": ("Apa yang diberikan kepada Nabi ﷺ dalam surah Al-Kautsar, dan apa yang diperintahkan sebagai gantinya?", ["Al-Kautsar; salat kepada Tuhannya dan berkurban", "Pasukan; berperang", "Kerajaan; memerintah", "Harta; membagikannya"], "«Sungguh, Kami telah memberimu Al-Kautsar. Maka laksanakanlah salat karena Tuhanmu dan berkurbanlah»."),
"prophets_221": ("Bagaimana surah At-Taubah menggambarkan Rasul ﷺ terhadap orang-orang beriman?", ["Sangat menginginkan kebaikan bagi mereka, penyantun dan penyayang", "Keras dan menjauh", "Kaya dan berkuasa", "Diam dan menyendiri"], "«Sungguh telah datang kepadamu seorang Rasul dari kaummu sendiri… dia sangat menginginkan kebaikan bagimu, penyantun dan penyayang terhadap orang-orang beriman»."),
"prophets_222": ("Menurut Al-Qur'an, apa yang akan menjauhkan orang dari Nabi ﷺ seandainya dia begitu?", ["Seandainya dia bersikap kasar dan berhati keras", "Seandainya dia kaya", "Seandainya dia muda", "Seandainya dia pendiam"], "«Maka berkat rahmat Allah engkau berlaku lemah lembut terhadap mereka. Sekiranya engkau bersikap kasar dan berhati keras, tentulah mereka menjauhkan diri dari sekitarmu»."),
"prophets_223": ("Apa yang Al-Qur'an katakan tentang Rasulullah ﷺ bagi orang yang mengharap Allah dan hari akhir?", ["Pada dirinya ada teladan yang baik bagi mereka", "Dia seorang raja", "Dia seorang hakim", "Dia seorang pemandu kafilah"], "«Sungguh, telah ada pada diri Rasulullah suri teladan yang baik bagimu, yaitu bagi orang yang mengharap rahmat Allah dan hari akhir»."),
"prophets_224": ("Kepada siapa Nabi Muhammad ﷺ diutus menurut surah Saba?", ["Kepada seluruh umat manusia", "Hanya kepada Quraisy", "Hanya kepada bangsa Arab", "Kepada penduduk Madinah"], "«Dan Kami tidak mengutus engkau melainkan kepada seluruh umat manusia sebagai pembawa berita gembira dan pemberi peringatan»."),
"prophets_225": ("Ayat apa yang Nabi ﷺ baca ketika berhala-berhala di sekitar Ka'bah disingkirkan?", ["«Kebenaran telah datang dan yang batil telah lenyap»", "«Kami telah memberimu kemenangan yang nyata»", "«Katakanlah: Dialah Allah Yang Maha Esa»", "«Apabila telah datang pertolongan Allah»"], "«Dan katakanlah: kebenaran telah datang dan yang batil telah lenyap; sungguh yang batil itu pasti lenyap»."),
"prophets_226": ("Apa yang orang beriman katakan tentang para rasul Allah di akhir surah Al-Baqarah?", ["«Kami tidak membeda-bedakan seorang pun dari rasul-rasul-Nya»", "«Kami hanya mengikuti yang terakhir»", "«Kami lebih menyukai salah satu»", "«Kami mengabaikan mereka»"], "«Kami tidak membeda-bedakan seorang pun dari rasul-rasul-Nya. Dan mereka berkata: kami dengar dan kami taat»."),
"prophets_227": ("Pesan bersama apa yang dibawa setiap rasul kepada kaumnya?", ["«Sembahlah Allah dan jauhilah tagut»", "«Bangunlah kuil»", "«Perkayalah dirimu»", "«Tulislah kitab»"], "«Dan sungguh, Kami telah mengutus seorang rasul untuk setiap umat: sembahlah Allah dan jauhilah tagut»."),
"prophets_228": ("Dengan bahasa apa setiap rasul diutus menurut surah Ibrahim?", ["Dengan bahasa kaumnya, agar dapat menjelaskan kepada mereka", "Hanya dengan bahasa Arab", "Dengan bahasa Ibrani", "Dengan bahasa langit"], "«Dan Kami tidak mengutus seorang rasul pun melainkan dengan bahasa kaumnya, agar dia dapat menjelaskan kepada mereka»."),
"prophets_229": ("Apa yang diwahyukan kepada setiap rasul sebelum Muhammad ﷺ menurut surah Al-Anbiya?", ["Bahwa tidak ada tuhan selain Dia: maka sembahlah Dia", "Membangun tempat suci", "Menaklukkan negeri", "Merahasiakannya"], "«Dan Kami tidak mengutus seorang rasul pun sebelum engkau melainkan Kami wahyukan kepadanya: tidak ada tuhan selain Aku, maka sembahlah Aku»."),
"prophets_230": ("Dalam surah Al-An'am, kelompok nabi manakah yang disebut sebagai keturunan Ibrahim yang diberi petunjuk?", ["Daud, Sulaiman, Ayyub, Yusuf, Musa, dan Harun antara lain", "Hanya Musa dan Isa", "Hanya Ismail dan Ishak", "Hanya Nuh dan Hud"], "Bagian itu menyebut deretan panjang nabi yang Allah beri petunjuk, dan berkata: «Demikianlah Kami memberi balasan kepada orang-orang yang berbuat baik»."),
"prophets_231": ("Apa yang Al-Qur'an katakan tentang para rasul satu sama lain?", ["Allah melebihkan sebagian mereka atas sebagian yang lain", "Semuanya sederajat", "Hanya yang terakhir yang berlaku", "Mereka tidak saling mengenal"], "«Rasul-rasul itu Kami lebihkan sebagian mereka atas sebagian yang lain»."),
"prophets_232": ("Perjanjian apa yang Allah ambil dari para nabi menurut surah Ali 'Imran?", ["Beriman kepada Rasul yang datang membenarkan apa yang ada pada mereka, dan menolongnya", "Tidak pernah meninggalkan kaumnya", "Masing-masing membangun kuil", "Masing-masing menulis kitab"], "«Jika datang kepadamu seorang Rasul yang membenarkan apa yang ada padamu, niscaya kamu sungguh-sungguh akan beriman kepadanya dan menolongnya»."),
"prophets_233": ("Nabi-nabi mana yang Al-Qur'an sebut ketika mengatakan Allah menetapkan agama yang sama bagi mereka?", ["Nuh, Ibrahim, Musa, dan Isa, beserta yang diwahyukan kepada Nabi ﷺ", "Hanya Adam dan Idris", "Hanya Daud dan Sulaiman", "Hanya Hud dan Saleh"], "«Dia telah mensyariatkan bagimu agama yang telah diwasiatkan-Nya kepada Nuh, dan yang telah Kami wahyukan kepadamu, dan yang telah Kami wasiatkan kepada Ibrahim, Musa, dan Isa»."),
"prophets_234": ("Apa yang Al-Qur'an katakan tentang rasul-rasul yang kisahnya tidak diceritakan?", ["Ada yang kisahnya tidak Allah ceritakan kepada Nabi ﷺ", "Mereka tidak ada", "Semuanya disebut namanya", "Mereka tidak penting"], "«Di antara mereka ada yang Kami ceritakan kepadamu dan di antara mereka ada yang tidak Kami ceritakan kepadamu»."),
"prophets_235": ("Dari siapa Allah memilih semua rasul-Nya menurut surah Yusuf?", ["Dari laki-laki penduduk negeri, yang Dia beri wahyu", "Dari malaikat", "Dari para raja", "Hanya dari penghuni padang pasir"], "«Dan Kami tidak mengutus sebelum engkau melainkan laki-laki yang Kami beri wahyu kepada mereka, dari penduduk negeri»."),
"prophets_236": ("Apa yang Al-Qur'an ingatkan tentang rasul-rasul yang didustakan sebelum Muhammad ﷺ?", ["Mereka bersabar sampai pertolongan Kami datang kepada mereka", "Mereka menyerah", "Mereka bersembunyi", "Mereka mengubah pesannya"], "«Dan sungguh, rasul-rasul sebelum engkau pun telah didustakan, tetapi mereka sabar terhadap pendustaan itu sampai datang pertolongan Kami kepada mereka»."),
"prophets_237": ("Keluarga mana yang Allah pilih atas seluruh alam menurut surah Ali 'Imran?", ["Adam, Nuh, keluarga Ibrahim, dan keluarga Imran", "Raja-raja Mesir", "Suku-suku Madinah", "Penduduk Saba"], "«Sesungguhnya Allah telah memilih Adam, Nuh, keluarga Ibrahim, dan keluarga Imran melebihi segala umat»."),
"prophets_238": ("Nikmat apa yang Musa ingatkan kepada kaumnya saat mengajak mereka memasuki Tanah Suci?", ["Bahwa Allah menjadikan nabi-nabi di antara mereka dan menjadikan mereka raja-raja", "Bahwa Dia memberi mereka kapal", "Bahwa Dia memberi mereka emas", "Bahwa Dia memberi mereka kuda"], "«Wahai kaumku! Ingatlah nikmat Allah kepadamu: Dia mengangkat nabi-nabi di antaramu dan menjadikan kamu raja-raja»."),
"prophets_239": ("Bagaimana Taurat dan Injil menggambarkan Nabi yang ummi menurut Al-Qur'an?", ["Dia menyuruh berbuat baik, melarang kemungkaran, dan menghilangkan beban mereka", "Dia membawa kekayaan", "Dia memerintah dengan kekerasan", "Dia membangun kuil"], "«…Nabi yang ummi yang mereka dapati tertulis dalam Taurat dan Injil yang ada pada mereka: dia menyuruh mereka berbuat baik dan melarang berbuat mungkar… dan menghilangkan beban mereka»."),
"prophets_240": ("Kepada siapa Nuh mengatakan dia bertawakal saat menantang kaumnya membuat tipu daya?", ["Kepada Allah, tempat dia bertawakal", "Kepada anak-anaknya", "Kepada kabilahnya", "Kepada kapalnya"], "«Maka kepada Allah aku bertawakal. Karena itu bulatkanlah keputusanmu bersama sekutu-sekutumu»."),
"prophets_241": ("Dalam doa Ibrahim, kepada siapa dia menisbatkan kesembuhan ketika sakit?", ["Kepada Allah semata", "Kepada para tabib", "Kepada tumbuhan", "Kepada waktu"], "«Dan apabila aku sakit, Dialah yang menyembuhkan aku», kata Ibrahim menggambarkan Tuhannya."),
"prophets_242": ("Dengan apa putra Ibrahim ditebus menurut surah As-Saffat?", ["Dengan sembelihan yang besar", "Dengan tebusan emas", "Dengan sebuah kafilah", "Dengan sekawanan ternak"], "«Dan Kami tebus anak itu dengan seekor sembelihan yang besar»."),
"prophets_243": ("Kepada apa orang beriman menyatakan iman dalam ayat «Katakanlah: kami beriman kepada Allah…»?", ["Kepada yang diturunkan kepada Ibrahim, Ismail, Ishak, Yakub, Musa, Isa, dan para nabi", "Kepada satu kitab saja", "Kepada satu nabi saja", "Kepada tradisi mereka sendiri"], "«Katakanlah: kami beriman kepada Allah dan apa yang diturunkan kepada kami, dan apa yang diturunkan kepada Ibrahim, Ismail, Ishak, Yakub…»"),
"prophets_244": ("Mengapa Allah menceritakan kisah para rasul kepada Nabi ﷺ?", ["Untuk meneguhkan hatinya", "Untuk menyibukkannya", "Untuk mengajarinya sejarah", "Untuk menghiburnya"], "«Dan semua kisah rasul-rasul yang Kami ceritakan kepadamu adalah kisah yang dengannya Kami teguhkan hatimu»."),
"prophets_245": ("Apa yang diperintahkan kepada Nabi ﷺ untuk dikatakan tentang dirinya di akhir surah Al-Kahfi?", ["«Aku hanyalah manusia seperti kamu; diwahyukan kepadaku bahwa Tuhanmu adalah Tuhan Yang Esa»", "«Aku seorang raja»", "«Aku seorang malaikat»", "«Aku mengetahui yang gaib»"], "«Katakanlah: aku ini hanyalah manusia seperti kamu, yang diwahyukan kepadaku bahwa Tuhanmu adalah Tuhan Yang Esa»."),
"prophets_246": ("Bagaimana surah Al-Fath menggambarkan mereka yang bersama Rasul ﷺ?", ["Keras terhadap orang kafir, berkasih sayang sesama mereka", "Kaya dan banyak", "Diam dan menyendiri", "Pengembara dan pedagang"], "«Muhammad adalah utusan Allah. Dan orang-orang yang bersama dengan dia bersikap keras terhadap orang-orang kafir, tetapi berkasih sayang sesama mereka»."),
"prophets_247": ("Apa yang surah An-Najm katakan tentang ucapan Nabi ﷺ?", ["Dia tidak berbicara menurut hawa nafsu: itu hanyalah wahyu yang diwahyukan", "Dia berbicara sebagai penyair", "Dia berbicara sebagai peramal", "Dia berbicara dari dirinya sendiri"], "«Kawanmu tidak sesat dan tidak keliru; dan tidaklah yang diucapkannya itu menurut hawa nafsu. Tidak lain itu adalah wahyu yang diwahyukan»."),
"prophets_248": ("Apa yang diperintahkan kepada Nabi ﷺ ketika pertolongan Allah dan kemenangan datang?", ["Bertasbih memuji Tuhannya dan memohon ampunan-Nya", "Merayakan dengan jamuan", "Mendirikan tugu", "Beristirahat"], "«Apabila telah datang pertolongan Allah dan kemenangan… maka bertasbihlah dengan memuji Tuhanmu dan mohonlah ampunan kepada-Nya»."),
"prophets_249": ("Tiga tugas apa yang surah Al-Jumu'ah berikan kepada Rasul yang diutus kepada kaum ummi?", ["Membacakan ayat-ayat, menyucikan mereka, dan mengajarkan Kitab dan hikmah", "Membangun, berdagang, dan memerintah", "Menulis, menghitung, dan bepergian", "Mengadili, menghukum, dan memungut pajak"], "«Dialah yang mengutus seorang Rasul kepada kaum yang buta huruf dari kalangan mereka sendiri, yang membacakan kepada mereka ayat-ayat-Nya, menyucikan mereka, dan mengajarkan kepada mereka Kitab dan hikmah»."),
"prophets_250": ("Perlindungan apa yang Al-Qur'an sebut selama Nabi ﷺ berada di tengah mereka?", ["Allah tidak akan mengazab mereka selama dia berada di tengah mereka", "Mereka akan kaya", "Mereka akan selalu menang", "Mereka tidak akan mati"], "«Dan Allah tidak akan mengazab mereka, sedang engkau berada di antara mereka»."),
}
